#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

int main()
{
    const std::string title{"Atlas of Stars"};
    const std::string_view prefix{title.data(), 5};
    std::vector<int> pages{4, 6, 8};
    const std::span<const int> entries{pages};
    pages[0] = 9;
    std::cout << prefix << '\n';
    std::cout << entries.front() << ' ' << entries.size() << '\n';
}
